import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { openTeamChangeHistory, ADMIN_ONLY_EVENTS } from './audit-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Team & Roles — Change history (#fc4fa4)', () => {
  test('Owner without super-admin rights sees Change history without coupon or plan events of his account #fc4fa4 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openTeamChangeHistory(page);

    // Блок отработал: либо пусто («No changes yet.»), либо события своей команды
    await expect(page.getByText('No changes yet.', { exact: true })
      .or(page.locator('tr, [role="row"]').filter({ hasText: /Role changed|Joined|Invited|Access turned|Moved to another business/ }))
      .first()).toBeVisible({ timeout: 30_000 });

    // Записи супер-админа по его аккаунту (купоны 11.11) в UI не попадают
    await expect(page.getByText(ADMIN_ONLY_EVENTS)).toHaveCount(0);
  });
});
